#define NLINK_FRAME_TIMEOUT_T1_COUNTS      9200U  /* the same in Timer1 counts (FC_PWM_COUNTS_PER_US; < FC_PWM_TOP + 1, for timer_elapsed_counts) */
/* fw09 W1: the NAV master's exchange watchdog (hal/nlink_spi.c nlink_spi_exchange_wait): an exchange that has not
 * ended NLINK_WD_COUNTS Timer3 counts (clk / 1; Timer3 restarts at 0 on every exchange) after its start is closed by the main loop.
 * Checked: 1000 us > 1.5 x NLINK_XFER_US 630 us and < FC_TICK_US 4000 us */
#define NLINK_WD_US                        1000UL  /* flight_computer.nlink.exchange_watchdog_us */
#define NLINK_WD_COUNTS                    16000u  /* NLINK_WD_US x F_CPU / 1e6 / 1 [Timer3 counts] */

